/**
 * The app's copy in Bengali.
 *
 * One flat map from the English source string to the Bengali it should read as.
 * `tx()` looks a screen's text up in it, so anything missing here simply stays
 * in English rather than showing an empty label — which is what lets a language
 * be shipped while it is still being filled in.
 *
 * The register is Bangladeshi Bangla, and it keeps the vocabulary a Bangladeshi
 * Muslim actually prays in rather than calquing the English: নামাজ for the
 * prayer, রোজা for the fast, অজু and গোসল for the washings, সেহরি and ইফতার
 * at either end of the day, পারা for a juz — the subcontinent term, not a
 * transliteration of juz — and কাজা for a make-up fast.
 *
 * Where the English is itself a translation of a fixed phrase, Bengali
 * translates it. Where the English keeps the Arabic, Bengali keeps it too.
 * The Prophet ﷺ is never named without the blessing.
 *
 * Bengali ends its sentences with a dari (।), not a full stop, and that is how
 * the sentences here are punctuated.
 */

