  'A rigid itinerary — the crowds will set your pace': 'একটি কঠোর সময়সূচি — ভিড়ই আপনার গতি ঠিক করবে',
  'A short charging cable and a spare': 'একটি ছোট চার্জিং কেবল ও একটি বাড়তি',
