  'A stretch of verses, both ends included — for learning a passage.': 'দুই প্রান্তসহ একটি আয়াতের অংশ — একটি অংশ শেখার জন্য।',
  'A tafsir, not a translation': 'একটি তাফসির, কোনো অনুবাদ নয়',
  'A thin folding prayer mat and unscented wipes': 'একটি পাতলা ভাঁজ করা জায়নামাজ ও সুগন্ধিমুক্ত ওয়াইপস',
  'A valid fast requires sincere intention and abstention from invalidators during the fasting day.': 'একটি বৈধ রোজার জন্য আন্তরিক নিয়ত ও রোজার দিনে রোজা ভঙ্গকারী বিষয় থেকে বেঁচে থাকা প্রয়োজন।',
  'A verse or hadith each day': 'প্রতিদিন একটি আয়াত বা হাদিস',
  'A white, clear discharge released at the end of the cycle. The Prophet ﷺ described it to Umm Atiyya as the sign that bleeding has ended, and women of the early generations would send word of it to one another.': 'চক্রের শেষে নির্গত একটি সাদা, স্বচ্ছ স্রাব। নবী ﷺ উম্মে আতিয়ার কাছে এটিকে রক্তপাত শেষ হওয়ার লক্ষণ হিসেবে বর্ণনা করেছেন, আর প্রথম যুগের নারীরা একে অপরকে এর খবর পাঠাতেন।',
  'A word at a time, and every root learned is a door that stays open long after these days have passed. Ten days of ten words is a hundred words carried into the rest of the year.': 'এক সময়ে একটি শব্দ, আর শেখা প্রতিটি মূল একটি দরজা যা এই দিনগুলো কেটে যাওয়ার পরও অনেকদিন খোলা থাকে। দশ দিনে দশটি শব্দ মানে বছরের বাকি সময়ে বয়ে নিয়ে যাওয়া একশ শব্দ।',
