  'An open Naskh with generous, clear diacritics': 'প্রশস্ত, স্পষ্ট হরকতসহ একটি খোলা নাসখ',
  'And what could make thee conceive what it is, that Night of Destiny?': 'আর কিসে আপনাকে জানাবে সেই কদরের রাত কী?',
  'Android is not allowing this app to set exact alarms, so the adhan cannot be timed to the prayer. Your notification tone will sound instead. Allow alarms and it will play properly.': 'অ্যান্ড্রয়েড এই অ্যাপকে নির্দিষ্ট অ্যালার্ম সেট করার অনুমতি দিচ্ছে না, তাই আজান নামাজের সময়ের সাথে মিলিয়ে দেওয়া যাচ্ছে না। এর বদলে আপনার বিজ্ঞপ্তির টোন বাজবে। অ্যালার্ম অনুমতি দিলে তা সঠিকভাবে বাজবে।',
  'Android sometimes delays alarms for apps it thinks are idle, which can make the adhan arrive late. Exempting this app takes one tap.': 'যেসব অ্যাপকে সে নিষ্ক্রিয় মনে করে তাদের অ্যালার্ম অ্যান্ড্রয়েড কখনো কখনো বিলম্বিত করে, যাতে আজান দেরিতে আসতে পারে। এই অ্যাপটিকে অব্যাহতি দিতে একটি ট্যাপ লাগে।',
  'Android will not delay this app’s reminders while it is saving power.': 'বিদ্যুৎ সাশ্রয় করার সময় অ্যান্ড্রয়েড এই অ্যাপের অনুস্মারক বিলম্বিত করবে না।',
  'Another sets no minimum at all, and counts any bleeding as hayd once it has begun.': 'অন্য মত কোনো সর্বনিম্ন ধার্য করে না, এবং শুরু হওয়ার পর যেকোনো রক্তপাত হায়েজ হিসেবে গণনা করে।',
