  'Bathe and dress in the Ihram garments, then make the intention for the rites you have chosen and begin the Talbiyah. The prohibitions of Ihram now apply until you have stoned, sacrificed and shaved or trimmed.': 'গোসল করুন ও ইহরামের কাপড় পরুন, তারপর আপনার বেছে নেওয়া রুকনের নিয়ত করুন ও তালবিয়া শুরু করুন। ইহরামের নিষেধসমূহ এখন প্রযোজ্য, যতক্ষণ না আপনি পাথর নিক্ষেপ করেছেন, কোরবানি দিয়েছেন ও চুল কামিয়েছেন বা ছেঁটেছেন।',
