  'Bleeding after childbirth is commonly counted up to 40 days.': 'প্রসবের পর রক্তপাত সাধারণত ৪০ দিন পর্যন্ত গণনা করা হয়।',
  'Bleeding after childbirth is commonly counted up to {n} days.': 'প্রসবের পর রক্তপাত সাধারণত {n} দিন পর্যন্ত গণনা করা হয়।',
  'Bleeding after childbirth is counted as nifas while it lasts, up to the outer limit. Its rules follow those of hayd for the days it runs.': 'প্রসবের পরের রক্তপাত যতক্ষণ চলে ততক্ষণ নেফাস হিসেবে গণনা করা হয়, সর্বোচ্চ সীমা পর্যন্ত। যে দিনগুলো তা চলে, সে দিনগুলোর বিধান হায়েজের অনুসরণ করে।',
  'Bleeding days': 'রক্তপাতের দিন',
  'Bleeding is not always hayd, and the difference decides whether the prayer and the fast are due. Answer the two questions below and the app will hold them against your own pattern and against the limits commonly cited.': 'রক্তপাত সবসময় হায়েজ নয়, আর এই পার্থক্যই নির্ধারণ করে নামাজ ও রোজা আবশ্যক কি না। নিচের দুটি প্রশ্নের উত্তর দিন, আর অ্যাপটি সেগুলোকে আপনার নিজের ধরন ও সাধারণভাবে উল্লিখিত সীমার সাথে মিলিয়ে দেখবে।',
  'Bleeding outside the pattern of hayd or nifas: ongoing spotting, a wound, or bleeding that runs past the limits above. It does not prevent the prayer or the fast. The well-known guidance is to wash, protect the area, and make wudu for the time of each prayer rather than once for the day.': 'হায়েজ বা নেফাসের ধরনের বাইরের রক্তপাত: চলমান সামান্য রক্তপাত, একটি ক্ষত, অথবা ওপরের সীমা অতিক্রম করে চলা রক্তপাত। এটি নামাজ বা রোজায় বাধা দেয় না। সুপরিচিত নির্দেশনা হলো ধুয়ে ফেলা, স্থানটি সুরক্ষিত করা, এবং দিনে একবারের বদলে প্রতি নামাজের সময়ের জন্য অজু করা।',
  'Bleeding that begins inside that gap is not counted as a new period.': 'সেই ফাঁকে শুরু হওয়া রক্তপাত নতুন হায়েজ হিসেবে গণনা হয় না।',
  'Bleeding that continues past the outer limit is treated as istihada from that point.': 'সর্বোচ্চ সীমা অতিক্রম করে চলতে থাকা রক্তপাত সেই মুহূর্ত থেকে ইস্তেহাজা হিসেবে ধরা হয়।',
