  'Days fasted in each month, oldest first.': 'প্রতি মাসে রাখা রোজার দিন, পুরনো থেকে শুরু।',
  'Days missed through hayd or nifas are made up one for one. There is no fidyah on them, because fidyah belongs to the one who cannot make the day up at all. A woman who can fast later fasts later.': 'হায়েজ বা নেফাসের কারণে বাদ পড়া দিন এক দিনের বিনিময়ে এক দিন আদায় করা হয়। তাদের ওপর কোনো ফিদইয়া নেই, কারণ ফিদইয়া তার জন্য যে মোটেই দিনটি আদায় করতে পারে না। পরে রোজা রাখতে পারেন এমন নারী পরেই রাখবেন।',
  'Days of Ramadan missed through menstruation or post-natal bleeding are made up before the next Ramadan, one day for each day. They do not need to be consecutive, and they may be spread through the year — but they are a debt, so most women keep a running count. This area records those days for you and keeps the scorecard honest as you settle them.': 'ঋতুস্রাব বা প্রসবোত্তর রক্তপাতের কারণে বাদ পড়া রমজানের দিন পরবর্তী রমজানের আগে, এক দিনের বিনিময়ে এক দিন আদায় করা হয়। সেগুলো ধারাবাহিক হতে হবে না, এবং বছরজুড়ে ছড়িয়ে দেওয়া যায় — কিন্তু সেগুলো একটি ঋণ, তাই অধিকাংশ নারী চলতি হিসাব রাখেন। এই বিভাগটি আপনার হয়ে সেই দিনগুলো রেকর্ড করে এবং আপনি সেগুলো আদায় করার সাথে সাথে স্কোরকার্ড সৎ রাখে।',
