  'Deutsch': 'Deutsch',
  'Dhikr': 'জিকির',
  'Dhikr counter': 'জিকির কাউন্টার',
  'Dhikr, dua, charity, kindness to family, listening to the Quran, and seeking knowledge all continue. Nothing about these days closes the door to a person’s relationship with Allah — they are part of the worship of a woman’s life, not a suspension of it. Many find the regular adhkar of morning and evening especially valuable here, since the habit continues even when the prayer does not.': 'জিকির, দোয়া, দান, পরিবারের প্রতি সদ্ব্যবহার, কুরআন শোনা ও জ্ঞান অন্বেষণ সবই অব্যাহত থাকে। এই দিনগুলোর কিছুই একজন মানুষের আল্লাহর সাথে সম্পর্কের দরজা বন্ধ করে দেয় না — সেগুলো একজন নারীর জীবনের ইবাদাতের অংশ, তার স্থগিতাদেশ নয়। অনেকে এখানে সকাল ও সন্ধ্যার নিয়মিত আজকারকে বিশেষভাবে মূল্যবান মনে করেন, কারণ নামাজ না হলেও অভ্যাসটি চলতে থাকে।',
