  'Downloads the Arabic script and translation you have selected, one Surah at a time. Preparation continues while you use other screens and prioritizes your current reading Surah.': 'আপনার বেছে নেওয়া আরবি লিপি ও অনুবাদ এক সময়ে একটি সূরা করে ডাউনলোড করে। আপনি অন্য স্ক্রিন ব্যবহার করলেও প্রস্তুতি চলতে থাকে এবং আপনার বর্তমান পঠিত সূরাকে অগ্রাধিকার দেয়।',
  'Drawn at random from what you are working on.': 'আপনি যা নিয়ে কাজ করছেন তা থেকে এলোমেলোভাবে নেওয়া।',
  'Dua': 'দোয়া',
  'Dua and remembrance': 'দোয়া ও জিকির',
  'Dua is worship, and it is never closed. The days in which the prayer is lifted from a woman are, by many accounts, days in which her asking is especially her own — nothing stands between her and it.': 'দোয়া ইবাদাত, আর তা কখনো বন্ধ হয় না। যে দিনগুলোতে একজন নারীর থেকে নামাজ ওঠে নেওয়া হয়, অনেক বর্ণনা অনুযায়ী সেই দিনগুলোতেই তার প্রার্থনা বিশেষভাবে তার নিজের — তার ও তার মাঝে কিছুই দাঁড়ায় না।',
