  'Each Hizb contains four quarter-Hizb sections.': 'প্রতি হিজবে চারটি চতুর্থাংশ-হিজব বিভাগ থাকে।',
  'Each Tajweed rule is coloured where it applies. Colours are a learning aid and do not replace study with a qualified teacher.': 'প্রতিটি তাজবিদের নিয়ম যেখানে প্রযোজ্য সেখানে রঙিন করা হয়। রঙ একটি শিক্ষার সহায়ক, এবং একজন যোগ্য শিক্ষকের সাথে অধ্যয়নের বিকল্প নয়।',
  'Each collection carries Arabic and English editions, so every hadith can be read in both. Collections are read on demand: opening one costs a single request for its list of books.': 'প্রতিটি সংগ্রহে আরবি ও ইংরেজি সংস্করণ থাকে, তাই প্রতিটি হাদিস উভয় ভাষায় পড়া যায়। সংগ্রহসমূহ চাহিদা অনুযায়ী পড়া হয়: একটি খুললে তার কিতাবের তালিকার জন্য একটি মাত্র অনুরোধ খরচ হয়।',
  'Each collection carries Arabic and English editions, so every hadith you read is shown in both. Nothing is paraphrased.': 'প্রতিটি সংগ্রহে আরবি ও ইংরেজি সংস্করণ থাকে, তাই আপনি যে হাদিসই পড়ুন তা উভয় ভাষায় দেখানো হয়। কিছুই পুনর্ব্যক্ত করা হয় না।',
  'Each morning': 'প্রতি সকালে',
  'Each press uncovers a few more words, so you are never completely stuck.': 'প্রতি চাপে আরও কয়েকটি শব্দ দেখা যায়, তাই আপনি কখনো পুরোপুরি আটকে যাবেন না।',
  'Each square is one day, oldest first. The fuller the square, the more of the five you marked.': 'প্রতিটি ঘর এক দিন, পুরনো থেকে শুরু। ঘর যত ভরা, পাঁচটির ততগুলো আপনি চিহ্নিত করেছেন।',
