  'End with salam to the right and left.': 'ডানে ও বামে সালাম দিয়ে শেষ করুন।',
  'English': 'English',
  'English meaning': 'ইংরেজি অর্থ',
  'Enter Ihram for Hajj if you have left it, and go to Mina, praying Dhuhr, ‘Asr, Maghrib, ‘Isha and Fajr there, each shortened to two rak‘ahs but not joined. Spend the night at Mina before going on to ‘Arafah.': 'আপনি যদি তা ছেড়ে থাকেন তবে হজের জন্য ইহরাম বাঁধুন, ও মিনায় যান, সেখানে জোহর, আসর, মাগরিব, এশা ও ফজর পড়ুন, প্রতিটি দুই রাকাতে কসর করে কিন্তু একত্র না করে। আরাফায় যাওয়ার আগে মিনায় রাত কাটান।',
  'Enter a label and valid latitude/longitude values.': 'একটি লেবেল ও বৈধ অক্ষাংশ/দ্রাঘিমাংশের মান লিখুন।',
