  'Every correction you have sent, kept here on your device. Resend it, copy it, or remove it.': 'আপনার পাঠানো প্রতিটি সংশোধন, আপনার ডিভাইসে এখানে রাখা। পুনরায় পাঠান, কপি করুন বা সরান।',
  'Every day': 'প্রতিদিন',
  'Every day owed, and every day settled': 'প্রতিদিনের বাকি ও প্রতিদিনের নিষ্পত্তি',
  'Every day you have marked, going back as far as your record does. A square is a day; the deeper the gold, the more of the five you prayed.': 'আপনার চিহ্নিত প্রতিদিন, আপনার রেকর্ড যতদূর যায় ততদূর পর্যন্ত। একটি ঘর একটি দিন; সোনালি যত গাঢ়, পাঁচটির ততগুলো আপনি পড়েছেন।',
  'Every day you have marked, on one map': 'আপনার চিহ্নিত প্রতিদিন, একটি মানচিত্রে',
  'Every letter': 'প্রতিটি অক্ষর',
  'Every occasion you open is stored locally, so it can be read again without a connection.': 'আপনার খোলা প্রতিটি অনুষ্ঠান স্থানীয়ভাবে সংরক্ষিত হয়, যাতে সংযোগ ছাড়াই আবার পড়া যায়।',
  'Every prayer you logged here has been made up.': 'আপনি এখানে লিপিবদ্ধ করা প্রতিটি নামাজের কাজা আদায় হয়েছে।',
  'Every recitation and every spoken translation, ayah by ayah, plus the full-Surah reciters drawn from all the providers behind one catalogue. Both adhan catalogues are served here too, though the recordings themselves ship inside the app so they can sound from a notification. Kept audio for a verse-by-verse reciter is the one thing still fetched whole from the Islamic Network CDN.': 'প্রতিটি তিলাওয়াত ও প্রতিটি কথ্য অনুবাদ, আয়াতে আয়াতে, সাথে একটি ক্যাটালগের পেছনের সব সরবরাহকারী থেকে নেওয়া পূর্ণ-সূরা ক্বারীগণ। দুটি আজান ক্যাটালগও এখানে পরিবেশন করা হয়, তবে রেকর্ডিংসমূহ নিজেরা অ্যাপের ভেতরে থাকে যাতে বিজ্ঞপ্তি থেকে বাজতে পারে। আয়াতে আয়াতে ক্বারীর জন্য রাখা অডিও একমাত্র জিনিস যা এখনো Islamic Network CDN থেকে পুরোটা আনা হয়।',
  'Every reminder this app has sent you. A past entry means it was sent — the system delivers notifications whether or not the app is open, so it cannot say whether you saw it.': 'এই অ্যাপ আপনাকে পাঠানো প্রতিটি অনুস্মারক। একটি অতীত এন্ট্রি মানে তা পাঠানো হয়েছে — অ্যাপ খোলা থাকুক বা না থাকুক সিস্টেম বিজ্ঞপ্তি পৌঁছে দেয়, তাই সে বলতে পারে না আপনি তা দেখেছেন কি না।',
  'Every rite is marked. You can keep the journey in your history, or start a fresh one the next time you go.': 'প্রতিটি রুকন চিহ্নিত। আপনি সফরটি আপনার ইতিহাসে রাখতে পারেন, অথবা পরের বার গেলে নতুন করে শুরু করতে পারেন।',
  'Every tap, toggle and counter answers with a small vibration': 'প্রতিটি ট্যাপ, টগল ও কাউন্টার সামান্য কম্পনে সাড়া দেয়',
  'Every time': 'প্রতিবার',
  'Every translation in every language, kept on this device. Around 725 MB of free space.': 'প্রতিটি ভাষার প্রতিটি অনুবাদ, এই ডিভাইসে রাখা। প্রায় ৭২৫ MB খালি স্থান প্রয়োজন।',
  'Every translation in every language.': 'প্রতিটি ভাষার প্রতিটি অনুবাদ।',
  'Everyone agrees that listening, studying the meaning, dhikr, dua, charity and seeking knowledge remain open. Where the disagreement falls, it falls on a narrow question — and a narrow question should not be allowed to swallow the whole month.': 'সবাই একমত যে শোনা, অর্থ অধ্যয়ন, জিকির, দোয়া, দান ও জ্ঞান অন্বেষণ খোলা থাকে। মতভেদ যেখানে পড়ে, তা একটি সরু প্রশ্নে পড়ে — আর একটি সরু প্রশ্নকে পুরো মাস গিলে ফেলতে দেওয়া উচিত নয়।',
  'Everything below is open to you today.': 'নিচের সবকিছু আজ আপনার জন্য খোলা।',
  'Everything else': 'অন্য সবকিছু',
  'Everything here changes the page behind this sheet': 'এখানে সবকিছু এই শিটের পেছনের পৃষ্ঠা বদলে দেয়',
  'Everything is rescheduled for you each day and whenever the location or these settings change.': 'প্রতিদিন এবং অবস্থান বা এই সেটিংস বদলালে সবকিছু আপনার হয়ে পুনর্নির্ধারিত হয়।',
  'Everything listed above': 'উপরে তালিকাভুক্ত সবকিছু',
  'Everything on this device is replaced by what is in the file.': 'এই ডিভাইসের সবকিছু ফাইলে যা আছে তা দিয়ে প্রতিস্থাপিত হবে।',
  'Everything that helps you keep a day of worship: the prayer times that move with the sun, the calendar that marks the month, and the records you keep for yourself.': 'যা কিছু আপনাকে একটি ইবাদাতের দিন রাখতে সাহায্য করে: সূর্যের সাথে সরে যাওয়া নামাজের সময়, মাস চিহ্নিত করা ক্যালেন্ডার, এবং আপনার নিজের জন্য রাখা রেকর্ডসমূহ।',
  'Everything the app opens is fetched from these public, keyless sources. No account, and no key, is needed for any of them.': 'অ্যাপ যা কিছু খোলে তা এই পাবলিক, কী-মুক্ত উৎস থেকে আনা হয়। তাদের কোনোটির জন্যই কোনো অ্যাকাউন্ট বা কী প্রয়োজন নেই।',
  'Exchange rates': 'বিনিময় হার',
  'Expensive jewellery': 'দামি গহনা',
  'Explore': 'অন্বেষণ',
  'Explore faith, life and spirituality': 'ঈমান, জীবন ও আধ্যাত্মিকতা অন্বেষণ করুন',
  'Explore the Quran by theme': 'বিষয় অনুযায়ী কুরআন অন্বেষণ করুন',
  'FASTS OWED': 'বাকি রোজা',
  'FEATURED READING': 'বিশেষ পাঠ',
  'FERTILE WINDOW': 'উর্বর সময়',
