  'FLOW': 'প্রবাহ',
  'FOR DHUHR, ASR, MAGHRIB AND ISHA': 'জোহর, আসর, মাগরিব ও এশার জন্য',
  'FOR FAJR ONLY': 'শুধু ফজরের জন্য',
  'Face ID': 'Face ID',
  'Face and fingerprint unlock are ready on this device': 'এই ডিভাইসে ফেস ও আঙুলের ছাপে আনলক প্রস্তুত',
  'Face masks, spare glasses or lenses, eye drops': 'ফেস মাস্ক, বাড়তি চশমা বা লেন্স, চোখের ড্রপ',
  'Face the Kaaba from where you stand': 'যেখানে দাঁড়িয়ে আছেন সেখান থেকে কাবার দিকে মুখ করুন',
  'Face the Qibla with intention.': 'নিয়তসহ কিবলার দিকে মুখ করুন।',
  'Failed': 'ব্যর্থ',
  'Faith': 'ঈমান',
  'Fajr': 'ফজর',
  'Fajr adhan': 'ফজরের আজান',
  'Fajr has its own call, chosen separately. All recordings are stored in the app.': 'ফজরের নিজস্ব আহ্বান আছে, আলাদাভাবে বেছে নেওয়া। সব রেকর্ডিং অ্যাপে সংরক্ষিত।',
  'Fajr has its own call, so it is chosen on its own. Every other prayer shares the second choice. All recordings are stored in the app and play with no connection.': 'ফজরের নিজস্ব আহ্বান আছে, তাই তা আলাদাভাবে বেছে নেওয়া হয়। অন্য সব নামাজ দ্বিতীয় পছন্দটি ভাগ করে। সব রেকর্ডিং অ্যাপে সংরক্ষিত ও সংযোগ ছাড়াই বাজে।',
  'Fajr only': 'শুধু ফজর',
  'Fast days missed through menstruation or the post-natal days are made up one for one, before the next Ramadan. This is the running count.': 'ঋতুস্রাব বা প্রসবোত্তর দিনের কারণে বাদ পড়া রোজার দিন পরবর্তী রমজানের আগে একটির বিনিময়ে একটি আদায় করা হয়। এটিই চলতি হিসাব।',
  'Fast days that fall in hayd or nifas are owed, and are kept here.': 'হায়েজ বা নেফাসে পড়া রোজার দিন বাকি থাকে, এবং এখানে রাখা হয়।',
  'Fast days that fall in them are not fasted, and are owed — the Qada screen will keep the count.': 'তাদের মধ্যে পড়া রোজার দিন রাখা হয় না, ও বাকি থাকে — কাজার স্ক্রিন হিসাব রাখবে।',
  'Faster': 'দ্রুততর',
  'Fasting': 'রোজা',
  'Fasting is due, and a fast kept in them counts — it is not owed again.': 'রোজা আবশ্যক, এবং তাদের মধ্যে রাখা রোজা গণ্য হয় — তা আর বাকি থাকে না।',
  'Fasting record': 'রোজার রেকর্ড',
  'Fasting timetable': 'রোজার সময়সূচি',
  'Fasting, and the days owed': 'রোজা, এবং বাকি দিনসমূহ',
  'Featured reading': 'বিশেষ পাঠ',
  'Feet': 'পা',
  'Fetched in 4 MB pieces, checked against the size the source reports, then saved.': '৪ MB করে টুকরো টুকরো করে আনা, উৎসের জানানো আকারের সাথে যাচাই করে সংরক্ষিত।',
  'Fetching…': 'আনা হচ্ছে…',
  'Fewer': 'কম',
  'Files are written to a temporary partial file first, checked against the size the server reported, and only then moved into place. A failed download is deleted rather than left half-written.': 'ফাইলসমূহ আগে একটি অস্থায়ী আংশিক ফাইলে লেখা হয়, সার্ভারের জানানো আকারের সাথে যাচাই করা হয়, আর তারপরই স্থানে সরানো হয়। একটি ব্যর্থ ডাউনলোড অর্ধলেখা রেখে দেওয়ার বদলে মুছে ফেলা হয়।',
  'Find the direction of the Kaaba': 'কাবার দিক খুঁজুন',
  'Finding steadiness of heart through remembrance of Allah.': 'আল্লাহর স্মরণের মাধ্যমে অন্তরের স্থিরতা খোঁজা।',
  'Fingerprint': 'আঙুলের ছাপ',
  'Finish this reading': 'এই পাঠ শেষ করুন',
  'Fix now': 'এখনই ঠিক করুন',
  'Flag a verse during practice and it will wait for you here.': 'অনুশীলনের সময় একটি আয়াত চিহ্নিত করলে তা আপনার জন্য এখানে অপেক্ষা করবে।',
  'Flagged': 'পতাকাঙ্কিত',
  'Flow': 'প্রবাহ',
  'Focus mode': 'ফোকাস মোড',
  'Follow the imam for the two-rakah prayer and additional takbirs.': 'দুই রাকাতের নামাজ ও অতিরিক্ত তাকবিরে ইমামের অনুসরণ করুন।',
  'Font size': 'ফন্টের আকার',
  'Food and drink': 'খাদ্য ও পানীয়',
  'For Eid al-Fitr, eat before leaving; for Eid al-Adha, local practice may differ.': 'ঈদুল ফিতরে, বের হওয়ার আগে কিছু খান; ঈদুল আজহায়, স্থানীয় আমল ভিন্ন হতে পারে।',
  'For formally entering Islam, connect with a trusted local mosque for support and learning.': 'আনুষ্ঠানিকভাবে ইসলাম গ্রহণের জন্য, সহায়তা ও শিক্ষার জন্য আপনার বিশ্বস্ত স্থানীয় মসজিদের সাথে যোগাযোগ করুন।',
  'For what you do in these specific days, ask a scholar you trust.': 'এই নির্দিষ্ট দিনগুলোতে আপনি যা করেন, তা জানতে আপনার বিশ্বস্ত কোনো আলেমকে জিজ্ঞাসা করুন।',
  'For women': 'নারীদের জন্য',
  'For your day': 'আপনার দিনের জন্য',
  'Forgiveness': 'ক্ষমা',
  'Form the intention and face the Qibla.': 'নিয়ত করুন ও কিবলার দিকে মুখ করুন।',
  'Forty': 'চল্লিশ',
  'Found online — saved on this device for next time.': 'অনলাইনে পাওয়া — পরের বারের জন্য এই ডিভাইসে সংরক্ষিত।',
  'Four digits. There is no reset link and no recovery email — this code lives on this device only, so choose one you will remember.': 'চারটি সংখ্যা। কোনো রিসেট লিংক নেই ও কোনো উদ্ধারমূলক ইমেইল নেই — এই কোডটি শুধু এই ডিভাইসে থাকে, তাই এমন একটি বেছে নিন যা আপনার মনে থাকবে।',
  'Four shortcuts, and which four is yours to say. Pick one to change it.': 'চারটি শর্টকাট, আর কোন চারটি তা আপনার ঠিক করার। বদলাতে একটি বেছে নিন।',
