  'GOD [Himself] proffers evidence - and [so do] the angels and all who are endowed with knowledge - that there is no deity save Him, the Upholder of Equity: there is no deity save Him, the Almighty, the Truly Wise.': 'আল্লাহ সাক্ষ্য দেন যে তিনি ছাড়া কোনো ইলাহ নেই, আর ফেরেশতারা ও জ্ঞানী ব্যক্তিরাও সাক্ষ্য দেন — তিনি ন্যায়ের ধারক: তিনি ছাড়া কোনো ইলাহ নেই, পরাক্রমশালী, প্রজ্ঞাময়।',
  'GOLD NISAB': 'সোনার নিসাব',
