  'Idghām without ghunnah': 'গুন্নাবিহীন ইদগাম',
  'If bleeding continues past what is usual for you, the commonly cited limits are fifteen days for hayd and forty for nifas. Beyond them, the bleeding is generally treated as istihadha: pray, fast, and speak to a scholar and a doctor. Neither of them will find the question unusual.': 'রক্তপাত আপনার স্বাভাবিকের চেয়ে দীর্ঘ হলে, সাধারণভাবে উল্লিখিত সীমা হলো হায়েজের জন্য পনেরো দিন ও নেফাসের জন্য চল্লিশ। এর বাইরে রক্তপাত সাধারণত ইস্তেহাজা হিসেবে ধরা হয়: নামাজ পড়ুন, রোজা রাখুন, এবং একজন আলেম ও একজন চিকিৎসকের সাথে কথা বলুন। তাদের কেউই এই প্রশ্নকে অস্বাভাবিক মনে করবেন না।',
  'If bleeding stops before Fajr and the fast is intended that night, the fast stands. Ghusl is required before the prayer; it is not a condition of the fast itself. A woman may wake in a state that defers Fajr and still hold a valid fast.': 'ফজরের আগে রক্তপাত বন্ধ হলে ও সেই রাতেই রোজার নিয়ত করা হলে, রোজাটি বহাল থাকে। নামাজের আগে গোসল আবশ্যক; এটি রোজার নিজের শর্ত নয়। একজন নারী এমন অবস্থায় ঘুম থেকে উঠতে পারেন যা ফজর পিছিয়ে দেয়, তবুও তার রোজা বৈধ থাকে।',
  'If this changes, this page changes with it.': 'এটি বদলালে এই পৃষ্ঠাও এর সাথে বদলাবে।',
