  'If you are not sure, leave it. The answer is firmer with it, but it is not required.': 'নিশ্চিত না হলে ছেড়ে দিন। এটি থাকলে উত্তর আরও পোক্ত হয়, তবে এটি আবশ্যক নয়।',
