  'Narrated Anas bin Malik:The Prophet (ﷺ) said, "Take Suhur as there is a blessing in it': 'আনাস বিন মালিক থেকে বর্ণিত: নবী ﷺ বলেছেন, "সেহরি খাও, কেননা তাতে বরকত আছে',
  'Narrated Talha bin `Abdullah bin `Auf:I offered the funeral prayer behind Ibn `Abbas and he recited Al-Fatiha and said, "You should know that it (i.e. recitation of Al-Fatiha) is the tradition of the Prophet Muhammad (ﷺ)': 'তালহা বিন আবদুল্লাহ বিন আওফ থেকে বর্ণিত: আমি ইবনে আব্বাসের পেছনে জানাজার নামাজ পড়লাম আর তিনি সূরা ফাতিহা পড়লেন ও বললেন, "জেনে রাখো যে তা (অর্থাৎ সূরা ফাতিহা পড়া) নবী মুহাম্মদ ﷺ এর সুন্নাত',
  'Narrator': 'বর্ণনাকারী',
  'Naskh': 'Naskh',
  'Natural bleeding that comes to a woman at its known time, without a cause such as injury or illness. Commonly cited limits are a minimum of three days and a maximum of fifteen, with at least fifteen days of purity between two cycles. Anything outside that pattern is usually treated as istihadha, and the details belong with a scholar.': 'প্রাকৃতিক রক্তপাত যা একজন নারীর কাছে তার জানা সময়ে আসে, আঘাত বা অসুস্থতার মতো কোনো কারণ ছাড়া। সাধারণভাবে উল্লিখিত সীমা হলো সর্বনিম্ন তিন দিন ও সর্বোচ্চ পনেরো, দুটি চক্রের মাঝে অন্তত পনেরো দিন পবিত্রতাসহ। এই ধরনের বাইরে যা কিছু তা সাধারণত ইস্তেহাজা হিসেবে ধরা হয়, আর বিস্তারিত একজন আলেমের কাছে যায়।',
