  'Not in the offline list, and the connection could not be reached. Continue and set it in Settings, where coordinates can be entered by hand.': 'অফলাইন তালিকায় নেই, এবং সংযোগে পৌঁছানো যায়নি। এগিয়ে যান ও সেটিংসে সেট করুন, সেখানে স্থানাংক হাতে লেখা যায়।',
  'Not notes on a verse — those live beside the ayah they belong to. This is only for you and the day you are in. Nothing is shared, and there is no streak to keep.': 'কোনো আয়াতের নোট নয় — সেগুলো যে আয়াতের তাই তার পাশে থাকে। এটি শুধু আপনার ও আপনি যে দিনে আছেন তার জন্য। কিছুই শেয়ার করা হয় না, আর রাখার মতো কোনো ধারাও নেই।',
