  'Notes and bookmarks you create remain yours and remain on your device.': 'আপনার তৈরি করা নোট ও বুকমার্ক আপনারই থাকে ও আপনার ডিভাইসেই থাকে।',
  'Notes in text': 'পাঠ্যের নোট',
  'Notes remain on this device and are never added to diagnostics.': 'নোটসমূহ এই ডিভাইসেই থাকে এবং কখনো ডায়াগনস্টিকসে যোগ করা হয় না।',
  'Notes where a verse runs on to the next page, so the sentence does not simply stop.': 'যেখানে একটি আয়াত পরের পৃষ্ঠায় চলে গেছে তার নোট, যাতে বাক্যটি হঠাৎ থেমে না যায়।',
  'Nothing came back for this collection': 'এই সংগ্রহের জন্য কিছুই ফেরত আসেনি',
