  'Nothing here is uploaded, backed up to an account, or used for anything else. Clearing the app data removes these records for good.': 'এখানে কিছুই আপলোড করা হয় না, কোনো অ্যাকাউন্টে ব্যাকআপ হয় না, বা অন্য কিছুতে ব্যবহৃত হয় না। অ্যাপের ডেটা মুছলে এই রেকর্ডসমূহ চিরতরে মুছে যায়।',
  'Nothing here yet': 'এখানে এখনো কিছু নেই',
  'Nothing is collected. No account, no analytics, no advertising identifier, no crash reporting that identifies you.': 'কিছুই সংগ্রহ করা হয় না। কোনো অ্যাকাউন্ট নেই, কোনো বিশ্লেষণ নেই, কোনো বিজ্ঞাপন শনাক্তকারী নেই, আপনাকে চিহ্নিত করে এমন কোনো ক্র্যাশ রিপোর্ট নেই।',
  'Nothing is playing': 'কিছুই চলছে না',
