  'Nothing recorded today': 'আজ কিছু রেকর্ড করা হয়নি',
  'Nothing recorded yet. Mark today above and your record starts here.': 'এখনো কিছু রেকর্ড করা হয়নি। উপরে আজকে চিহ্নিত করলে আপনার রেকর্ড এখান থেকে শুরু।',
