  'Nūn sākin or tanwīn changes toward a concealed mīm before bāʾ.': 'বা-এর আগে নূন সাকিন বা তানবিন গোপন মীমের দিকে বদলে যায়।',
  'O Allah, send blessings upon Muhammad': 'হে আল্লাহ, মুহাম্মদের ওপর রহমত নাজিল করুন',
  'O YOU who have attained to faith! Fasting is ordained for you as it was ordained for those before you, so that you might remain conscious of God:': 'হে ঈমানদারগণ! তোমাদের ওপর রোজা ফরজ করা হয়েছে যেভাবে তোমাদের আগেরদের ওপর ফরজ করা হয়েছিল, যাতে তোমরা আল্লাহভীরু হও:',
