  'Observed by many Muslims; others do not mark it. Neither position is stated here as the only one.': 'অনেক মুসলমান পালন করেন; অন্যরা পালন করেন না। এখানে কোনো অবস্থানই একমাত্র বলে দেওয়া হচ্ছে না।',
  'Of the five': 'পাঁচটির মধ্যে',
  'Off': 'বন্ধ',
  'Official coverage from the holy sites — Arafah, Muzdalifah and Mina. The channel is live during the days of Hajj and carries other programming for the rest of the year.': 'পবিত্র স্থানসমূহ — আরাফা, মুজদালিফা ও মিনা — থেকে দাপ্তরিক সম্প্রচার। চ্যানেলটি হজের দিনগুলোতে লাইভ থাকে এবং বছরের বাকি সময় অন্যান্য অনুষ্ঠান বহন করে।',
  'Offline': 'অফলাইন',
