  'Offline · ': 'অফলাইন · ',
  'Omani Rial': 'ওমানি রিয়াল',
  'On': 'চালু',
  'On reaching Makkah, perform the arrival Tawaf of seven circuits and pray two rak‘ahs. For Tamattu‘, follow it with the Sa‘i of Hajj (or keep the Sa‘i for after Tawaf al-Ifādah — both are held valid by different schools). You then remain in Ihram.': 'মক্কায় পৌঁছে আগমনের তাওয়াফ হিসেবে সাত চক্কর করুন ও দুই রাকাত নামাজ পড়ুন। তামাত্তুর জন্য এর পর হজের সাঈ করুন (অথবা সাঈ তাওয়াফে ইফাদার পরের জন্য রেখে দিন — উভয়ই বিভিন্ন মাজহাবে বৈধ ধরা হয়)। এরপর আপনি ইহরামেই থাকবেন।',
  'On the streak': 'ধারায় আছেন',
  'On this device': 'এই ডিভাইসে',
  'On what you have entered, this falls inside your own pattern and inside the limits commonly cited. Prayer and fasting are not due in these days.': 'আপনি যা লিখেছেন তার ভিত্তিতে, এটি আপনার নিজের ধরনের মধ্যে ও সাধারণভাবে উল্লিখিত সীমার মধ্যে পড়ে। এই দিনগুলোতে নামাজ ও রোজা আবশ্যক নয়।',
  'On your device': 'আপনার ডিভাইসে',
  'Once a day is actually missed, keep it here.': 'একটি দিন আসলেই বাদ পড়লে, তা এখানে রাখুন।',
  'One a day is enough for most people. The pace only sets the estimate above — nothing is scheduled for you.': 'অধিকাংশ মানুষের জন্য দিনে একটি যথেষ্ট। গতি শুধু ওপরের অনুমানটি ঠিক করে — আপনার জন্য কিছুই নির্ধারিত করা হয় না।',
  'One day earlier': 'এক দিন আগে',
  'One day later': 'এক দিন পরে',
  'One fewer': 'একটি কম',
  'One fewer day owed': 'এক দিন কম বাকি',
  'One file for the whole Surah.': 'পুরো সূরার জন্য একটি ফাইল।',
  'One hadith each morning, at the hour you choose.': 'প্রতি সকালে একটি হাদিস, আপনার বেছে নেওয়া সময়ে।',
  'One more': 'আরও একট',
  'One more day owed': 'আরও এক দিন বাকি',
  'One of thirty equal parts, so the Quran can be read across a month': 'ত্রিশটি সমান অংশের একটি, যাতে এক মাসে কুরআন পড়া যায়',
  'One position sets a minimum length for hayd, so bleeding shorter than it is not a period and prayer remains due.': 'একটি মত হায়েজের একটি সর্বনিম্ন দৈর্ঘ্য ধার্য করে, তাই তার চেয়ে কম সময়ের রক্তপাত হায়েজ নয় ও নামাজ বহাল থাকে।',
  'One reminder in the morning, and a nudge back to where you were reading.': 'সকালে একটি অনুস্মারক, এবং আপনি যেখানে পড়ছিলেন সেখানে ফেরার একটি ইশারা।',
  'One verse each morning, at the hour you choose.': 'প্রতি সকালে একটি আয়াত, আপনার বেছে নেওয়া সময়ে।',
  'Only changes what new entries are recorded in — past gifts keep the currency they were given in.': 'শুধু নতুন এন্ট্রি কোন মুদ্রায় লেখা হবে তা বদলায় — আগের উপহারসমূহ যে মুদ্রায় দেওয়া হয়েছিল তাতেই থাকে।',
  'Only languages that are published are listed. Others are not shown rather than faked.': 'শুধু প্রকাশিত ভাষাসমূহই তালিকাভুক্ত। অন্যগুলো দেখানো হয় না, বানানো হয় না।',
