  'Open to you without question — no school disputes it. Put a reciter on and let the day be filled with the sound of it. Listening is not a lesser substitute for reciting; it is its own worship, and these are often the days a woman listens most.': 'আপনার জন্য নিঃসন্দেহে খোলা — কোনো মাজহাবই তা নিয়ে দ্বিমত করে না। একটি ক্বারী চালু করে দিন আর দিনটি তার ধ্বনিতে ভরে যাক। শোনা তিলাওয়াতের কোনো নিম্নমানের বিকল্প নয়; এটি নিজেই একটি ইবাদাত, আর প্রায়ই এই দিনগুলোতেই একজন নারী সবচেয়ে বেশি শোনেন।',
  'Open verse actions to add a reflection.': 'একটি চিন্তা যোগ করতে আয়াতের কাজসমূহ খুলুন।',
