  'Permission was declined earlier, so reminders stay off. You can turn them on in the system settings for this app at any time.': 'অনুমতি আগে প্রত্যাখ্যাত হয়েছিল, তাই অনুস্মারক বন্ধ আছে। আপনি যেকোনো সময় এই অ্যাপের জন্য সিস্টেম সেটিংসে তা চালু করতে পারেন।',
