  'Pray two rak‘ahs and give thanks': 'দুই রাকাত নামাজ পড়ুন ও কৃতজ্ঞতা জানান',
  'Pray where you can in the Haram, give charity if you are able, and keep the supplication that is offered after a completed rite. Many then repeat the Umrah from Al-Tan‘īm or perform it again for someone else — that is a matter of your own intention and capacity.': 'হারামে যখানে পারেন নামাজ পড়ুন, পারলে দান করুন, আর একটি রুকন পূর্ণ হওয়ার পর যে দোয়া করা হয় তা চালিয়ে যান। অনেকে এরপর তানঈম থেকে উমরা পুনরায় করেন বা অন্য কারো হয়ে তা করেন — তা আপনার নিজের নিয়ত ও সামর্থ্যের বিষয়।',
  'Prayer': 'নামাজ',
  'Prayer Reminders': 'নামাজের অনুস্মারক',
  'Prayer and fasting are due': 'নামাজ ও রোজা বাকি',
  'Prayer and fasting are not due in these days': 'এই দিনগুলোতে নামাজ ও রোজা আবশ্যক নয়',
  'Prayer and fasting are not due while it continues, and the fasts are owed.': 'তা চলতে থাকাকালে নামাজ ও রোজা আবশ্যক নয়, এবং রোজাগুলো বাকি থাকে।',
  'Prayer and fasting resume from here': 'নামাজ ও রোজা এখান থেকে শুরু',
  'Prayer and fasting resume from here, and a fast kept after the ghusl counts.': 'নামাজ ও রোজা এখান থেকে শুরু, এবং গোসলের পর রাখা রোজা গণ্য হয়।',
  'Prayer and fasting resume from here, and the fasts of these days count.': 'নামাজ ও রোজা এখান থেকে শুরু, এবং এই দিনগুলোর রোজা গণ্য হয়।',
  'Prayer during the monthly cycle': 'মাসিক চক্রের সময় নামাজ',
  'Prayer is due in these days, and the prayer of each one is prayed.': 'এই দিনগুলোতে নামাজ আবশ্যক, এবং প্রতিটির নামাজ পড়া হয়।',
  'Prayer record, reading position, bookmarks, notes, settings, chosen city and language. Removed by clearing storage or uninstalling.': 'নামাজের রেকর্ড, পাঠের অবস্থান, বুকমার্ক, নোট, সেটিংস, বেছে নেওয়া শহর ও ভাষা। স্টোরেজ মুছলে বা আনইনস্টল করলে মুছে যায়।',
  'Prayer reminders': 'নামাজের অনুস্মারক',
  'Prayer reminders are ready': 'নামাজের অনুস্মারক প্রস্তুত',
  'Prayer schedule': 'নামাজের সময়সূচি',
  'Prayer spaces around you': 'আপনার আশেপাশে নামাজের জায়গা',
  'Prayer times': 'নামাজের সময়',
  'Prayer times, Qibla and fasting times read from one place. Tap to choose a city or enter coordinates.': 'নামাজের সময়, কিবলা ও রোজার সময় এক জায়গা থেকে পড়া। একটি শহর বেছে নিতে বা স্থানাংক লিখতে স্পর্শ করুন।',
  'Prayer times, Qibla and the fasting timetable all read from one place. Search for your city, or use your location once. This is asked only here — you can change it any time in Settings.': 'নামাজের সময়, কিবলা ও রোজার সময়সূচি সব এক জায়গা থেকে পড়া। আপনার শহর অনুসন্ধান করুন, অথবা একবার আপনার অবস্থান ব্যবহার করুন। এটি শুধু এখানেই জিজ্ঞাসা করা হয় — আপনি যেকোনো সময় সেটিংসে বদলাতে পারেন।',
  'Prayer times, Qibla, Ramadan and nearby mosques all read from this one place. It is asked once and kept on this device.': 'নামাজের সময়, কিবলা, রমজান ও আশেপাশের মসজিদ সব এই এক জায়গা থেকে পড়া। এটি একবার জিজ্ঞাসা করা হয় ও এই ডিভাইসে রাখা হয়।',
  'Prayer times, the Hijri date, the Ramadan timetable, and the 604-page Mushaf layout with the Juz and Hizb divisions — kept with the app rather than asked for, so a page of the Quran opens without a connection. Every adhan recording is stored here too, eighteen for the day and two for dawn, which is what lets the call sound at Fajr with no network at all. The sun does not need the internet, and nothing about where you are is sent anywhere.': 'নামাজের সময়, হিজরি তারিখ, রমজানের সময়সূচি, এবং পারা ও হিজব বিভাজনসহ ৬০৪-পৃষ্ঠার মুসহফের বিন্যাস — চেয়ে আনার বদলে অ্যাপের সাথেই রাখা, তাই সংযোগ ছাড়াই কুরআনের একটি পৃষ্ঠা খোলে। প্রতিটি আজানের রেকর্ডিংও এখানে সংরক্ষিত, দিনের জন্য আঠারোটি ও ভোরের জন্য দুটি, যা ফজরে কোনো নেটওয়ার্ক ছাড়াই আহ্বান বাজতে দেয়। সূর্যের ইন্টারনেটের দরকার নেই, আর আপনি কোথায় আছেন তা সম্পর্কে কিছুই কোথাও পাঠানো হয় না।',
