  'Prayer, Qibla, Ramadan, and mosque tools share this saved location. It stays on this device.': 'নামাজ, কিবলা, রমজান ও মসজিদের টুল এই সংরক্ষিত অবস্থান ব্যবহার করে। এটি এই ডিভাইসেই থাকে।',
