  'Quran Audio': 'কুরআন অডিও',
  'Quran TV and Sunnah TV play right here, from the broadcaster’s own stream. The other channels open outside this app, because carrying them here would need rights the app does not hold.': 'কুরআন টিভি ও সুন্নাহ টিভি এখানেই বাজে, সম্প্রচারকের নিজস্ব স্ট্রিম থেকে। অন্য চ্যানেলগুলো এই অ্যাপের বাইরে খোলে, কারণ সেগুলো এখানে বহন করতে এমন স্বত্ব দরকার যা অ্যাপের নেই।',
