  'Quran cache {u} MB · limit {l} MB · total limit {t} MB': 'কুরআন ক্যাশ {u} MB · সীমা {l} MB · মোট সীমা {t} MB',
  'Quran notes': 'কুরআনের নোট',
  'Quran preparation stopped because live data could not be reached.': 'লাইভ তথ্যে পৌঁছানো যায়নি বলে কুরআনের প্রস্তুতি থেমে গেছে।',
  'Quran reading': 'কুরআন পাঠ',
  'Quran reminder': 'কুরআনের অনুস্মারক',
  'Quran search': 'কুরআন অনুসন্ধান',
  'Quran study tools': 'কুরআন অধ্যয়নের টুল',
  'Quran text, hadith, the Names and the supplications come from the sources named in the app. Rulings and guidance are summarised for learning; for a matter that affects your worship or your obligations, ask a qualified scholar. This app is not a source of legal or religious authority.': 'কুরআনের পাঠ্য, হাদিস, নামসমূহ ও দোয়াসমূহ অ্যাপে নাম দেওয়া উৎস থেকে আসে। বিধান ও নির্দেশনা শিক্ষার জন্য সংক্ষিপ্ত করা হয়েছে; আপনার ইবাদাত বা দায়িত্বকে প্রভাবিত করে এমন বিষয়ে একজন যোগ্য আলেমকে জিজ্ঞাসা করুন। এই অ্যাপ কোনো আইনি বা ধর্মীয় কর্তৃত্বের উৎস নয়।',
  'Quran text, prayer times, hadith, the Names, supplications and the countdown to Hajj come from api.islamicdata.uz. Recitation audio comes from cdn.islamic.network. The adhan recordings you choose are downloaded from audio.islamicdata.uz. Gold and silver prices used by the Zakat calculator come from misc.islamicdata.uz. Each of these receives the request needed to answer it and nothing about you.': 'কুরআনের পাঠ্য, নামাজের সময়, হাদিস, নামসমূহ, দোয়াসমূহ ও হজের কাউন্টডাউন আসে api.islamicdata.uz থেকে। তিলাওয়াতের অডিও আসে cdn.islamic.network থেকে। আপনার বেছে নেওয়া আজানের রেকর্ডিং ডাউনলোড হয় audio.islamicdata.uz থেকে। যাকাত ক্যালকুলেটরে ব্যবহৃত সোনা ও রূপার দাম আসে misc.islamicdata.uz থেকে। তাদের প্রতিটি তার উত্তর দেওয়ার জন্য প্রয়োজনীয় অনুরোধ পায়, আর আপনার সম্পর্কে কিছুই নয়।',
