  'Sahih Muslim — the hadith of Umm Atiyya on the signs of purity': 'সহিহ মুসলিম — পবিত্রতার লক্ষণ সম্পর্কে উম্মে আতিয়ার হাদিস',
  'Sahih al-Bukhari and Muslim — “Do what the pilgrim does, except do not circumambulate the House”': 'সহিহ বুখারি ও মুসলিম — "হাজি যা করে তুমিও তা কর, তবে ঘরের তাওয়াফ করবে না"',
  'Sahih al-Bukhari, Kitab al-Hayd — the hadith of Aisha on making up fasts, not prayers': 'সহিহ বুখারি, কিতাবুল হায়েজ — রোজার কাজা করা, নামাজের নয়, বিষয়ে আয়েশার হাদিস',
