  'Salah Tracker': 'নামাজ ট্র্যাকার',
  'Salah counts the prayers you mark on the Prayer screen. Reading counts the verses you mark in the reader and the Mushaf pages you open. Dhikr comes from the Tasbih counter, and hifz from every verse you rate in recall practice. The week is kept on this device only.': 'সালাহ গণনা করে আপনি নামাজের স্ক্রিনে যত নামাজ চিহ্নিত করেন। রিডিং গণনা করে আপনি পাঠকে যত আয়াত চিহ্নিত করেন ও যত মুসহফ পৃষ্ঠা খুলেন। জিকির আসে তাসবিহ কাউন্টার থেকে, আর হিফজ স্মরণ অনুশীলনে আপনি যে প্রতিটি আয়াত রেট করেন তা থেকে। সপ্তাহটি শুধু এই ডিভাইসে রাখা হয়।',
  'Salah counts the prayers you mark on the Prayer screen. Reading counts the verses you mark in the reader and the Mushaf pages you open. Dhikr comes from the Tasbih counter, and hifz from every verse you rate in recall practice. Thirty days are kept, on this device only, and nothing is uploaded.': 'সালাহ গণনা করে আপনি নামাজের স্ক্রিনে যত নামাজ চিহ্নিত করেন। রিডিং গণনা করে আপনি পাঠকে যত আয়াত চিহ্নিত করেন ও যত মুসহফ পৃষ্ঠা খুলেন। জিকির আসে তাসবিহ কাউন্টার থেকে, আর হিফজ স্মরণ অনুশীলনে আপনি যে প্রতিটি আয়াত রেট করেন তা থেকে। ত্রিশ দিন রাখা হয়, শুধু এই ডিভাইসে, আর কিছুই আপলোড করা হয় না।',
  'Salat al-Janazah is a communal obligation and is performed standing, without bowing or prostration.': 'সালাতুল জানাজা একটি ফরজে কেফায়া, আর তা দাঁড়িয়ে আদায় করা হয়, কোনো রুকু বা সিজদা ছাড়া।',
