  'Scheherazade New': 'Scheherazade New',
  'Scholars differ on which of the two to measure against. The lower threshold brings more wealth into Zakat; take the choice to someone you trust.': 'দুটির কোনটির বিপরীতে মাপতে হবে তা নিয়ে আলেমগণ ভিন্নমত পোষণ করেন। নিচের সীমা যাকাতে বেশি সম্পদ আনে; পছন্দটি আপনার বিশ্বস্ত কারো কাছে নিয়ে যান।',
  'Scholars differ. Reciting from memory is widely permitted; touching the physical mushaf is not, since it requires purification. On screens and phones the question turns on whether a device counts as a mushaf — many contemporary scholars permit reading and reciting from a phone for that reason, while others advise limiting it to looking and listening. Follow the position of a scholar you trust, and keep the Quran close either way: listening to recitation is open to everyone, in every state.': 'আলেমগণ ভিন্নমত পোষণ করেন। মুখস্থ থেকে তিলাওয়াত ব্যাপকভাবে অনুমোদিত; মুসহফ স্পর্শ করা নয়, কারণ তাতে পবিত্রতা দরকার। স্ক্রিন ও ফোনে প্রশ্নটি ঘোরে একটি ডিভাইস মুসহফ হিসেবে গণ্য হয় কি না — অনেক সমসাময়িক আলেম সেই কারণে ফোন থেকে পড়া ও তিলাওয়াতের অনুমতি দেন, আবার অন্যরা তা দেখা ও শোনার মধ্যেই সীমিত রাখার পরামর্শ দেন। আপনি যে আলেমকে বিশ্বাস করেন তার অবস্থান অনুসরণ করুন, আর যেভাবেই হোক কুরআন কাছে রাখুন: তিলাওয়াত শোনা সবার জন্য, সব অবস্থাতেই খোলা।',
