  'VERSE': 'আয়াত',
  'VERSES MARKED': 'চিহ্নিত আয়াত',
  'Verse': 'আয়াত',
  'Verse by verse': 'আয়াতে আয়াতে',
  'Verse notes': 'আয়াতের নোট',
  'Verse of the day': 'দিনের আয়াত',
  'Verse queue · saved {d}': 'আয়াতের কিউ · সংরক্ষিত {d}',
  'Verse reference': 'আয়াতের সূত্র',
  'Verse {v} continued from page {p}': 'আয়াত {v} পৃষ্ঠা {p} থেকে চলছে',
  'Verse {v} continues on page {p}': 'আয়াত {v} পৃষ্ঠা {p} এ চলছে',
  'Verse, Name and adhkar of the day': 'দিনের আয়াত, নাম ও আজকার',
  'Verse-by-verse files, one track per ayah, with translation audio and reader controls.': 'আয়াতে আয়াতে ফাইল, প্রতি আয়াতের জন্য একটি ট্র্যাক, অনুবাদের অডিও ও পাঠকের নিয়ন্ত্রণসহ।',
  'Verse-by-verse: one track for each ayah. Full-Surah: a complete recitation of the Surah.': 'আয়াতে আয়াতে: প্রতি আয়াতের জন্য একটি ট্র্যাক। পূর্ণ-সূরা: সূরার একটি সম্পূর্ণ তিলাওয়াত।',
  'Verses': 'আয়াতসমূহ',
  'Verses affirming the absolute oneness, independence and incomparability of Allah.': 'আল্লাহর পরম একত্ব, অমুখাপেক্ষিতা ও অতুলনীয়তা নিশ্চিত করা আয়াতসমূহ।',
  'Verses under this are drawn more often. Anything you flag yourself counts as weak whatever it scores.': 'এর নিচের আয়াতগুলো বেশি বার আনা হয়। আপনি নিজে যা চিহ্নিত করেন তা যাই স্কোর করুক না কেন, দুর্বল হিসেবেই গণ্য।',
  'Version': 'সংস্করণ',
