  'Where the Quran text, prayer times, hadith and audio come from': 'কুরআনের পাঠ্য, নামাজের সময়, হাদিস ও অডিও কোথা থেকে আসে',
  'Where the scholars differ': 'আলেমগণ কোথায় ভিন্নমত পোষণ করেন',
