  'Which colours the app wears. Each theme has its own light and dark.': 'অ্যাপটি কোন রঙ পরে। প্রতিটি থিমের নিজস্ব লাইট ও ডার্ক আছে।',
  'Which fasts your cycle may claim, and when they fall due': 'আপনার চক্র কোন রোজাগুলো দাবি করতে পারে, ও সেগুলো কখন বাকি পড়ে',
  'Which language should the app speak?': 'অ্যাপটি কোন ভাষায় কথা বলবে?',
  'Which meaning beside the Arabic?': 'আরবির পাশে কোন অর্থ?',
