  'Which position this uses': 'এটি কোন অবস্থান ব্যবহার করে',
  'Which voice with the recitation?': 'তিলাওয়াতের সাথে কোন ক্বারী?',
  'Who we ask': 'আমরা কাকে জিজ্ঞাসা করি',
  'Who we ask about': 'আমরা কার সম্পর্কে জিজ্ঞাসা করি',
  'Wipe the head and ears.': 'মাথা ও কান মাসেহ করুন।',
  'With no recorded pattern to measure against, the outer limit is what there is to go on.': 'মাপার মতো কোনো রেকর্ডকৃত ধরন না থাকলে, সর্বোচ্চ সীমাই একমাত্র ভিত্তি।',
  'Without end is the default: you stop when you know it, not when a counter runs out.': 'কোনো শেষ না থাকাই ডিফল্ট: আপনি জানলে থামেন, কোনো কাউন্টার শেষ হলে নয়।',
  'Witr': 'বিতর',
  'Witr, Duha and Tahajjud are voluntary, so they are kept apart from the five. Counting them together would flatter the obligation and turn these into a task.': 'বিতর, দোহা ও তাহাজ্জুদ নফল, তাই সেগুলো পাঁচ ওয়াক্ত থেকে আলাদা রাখা হয়। সেগুলো একসাথে গণনা করলে ফরজকে ফুলিয়ে দেখানো হবে ও এগুলোকে একটি কাজে পরিণত করা হবে।',
  'Witr, Duha and Tahajjud, kept apart from the five': 'বিতর, দোহা ও তাহাজ্জুদ, পাঁচ ওয়াক্ত থেকে আলাদা',
