  'Work out what is due, and record what you gave': 'কী বাকি তা হিসাব করুন, ও যা দিয়েছেন তা লিপিবদ্ধ করুন',
  'Worked out from your attempts, never set by hand — so correcting one moves this immediately.': 'আপনার প্রচেষ্টা থেকে হিসাব করা, কখনো হাতে সেট করা নয় — তাই একটি সংশোধন করলে এটি সাথে সাথে সরে।',
