  'Your cycle has varied a good deal, so this is a rough shape rather than a forecast.': 'আপনার চক্র অনেকটাই ভিন্ন, তাই এটি একটি পূর্বাভাসের বদলে একটি মোটামুটি রূপ।',
  'Your cycle varies somewhat, so treat the outer days as a question mark.': 'আপনার চক্র কিছুটা ভিন্ন, তাই শেষ দিনগুলোকে প্রশ্নবোধক হিসেবে দেখুন।',
